<?php
namespace qqworld_collector\module\collect_item; use qqworld_collector\lib; class comment_date extends lib { var $guid; public function init() { add_filter( 'qqworld-collector-collecting-engine-collect-item-' . $this->guid, array($this, 'filter'), 10, 7 ); add_filter( 'qqworld-collector-collecting-engine-collect-item-after-filter-' . $this->guid, array($this, 'after_filter'), 10, 6 ); } public function filter($items, $args, $source_link, $html, $download_args, $settings, $mode) { return $items; } public function after_filter($items, $args, $source_link, $html, $settings, $mode) { $items = strip_tags(trim($items)); $now = date('Y-m-d H:i:s', current_time('timestamp')); if (preg_match('/^(\d*)分钟前/i', $items, $match)) { $items = date("Y-m-d H:i:s", strtotime("-".$match[1]."minutes", strtotime($now))); } elseif (preg_match('/^(\d*)小时前/i', $items, $match)) { $items = date("Y-m-d H:i:s", strtotime("-".$match[1]."hours", strtotime($now))); } elseif (preg_match('/^(\d*)天前/i', $items, $match)) { $items = date("Y-m-d H:i:s", strtotime("-".$match[1]."days", strtotime($now))); } elseif (preg_match('/^(\d*)周前/i', $items, $match)) { $items = date("Y-m-d H:i:s", strtotime("-".$match[1]."weeks", strtotime($now))); } if (!strtotime($items)) $items = $now; return $items; } } ?>